const { accel, gyro, temperature } = msg.payload;
const now = Date.now();
const last = context.get('t') || now;
const dt = Math.min(0.5, (now - last) / 1000);
context.set('t', now);
const D = 180 / Math.PI;
// accelerometer-only angles (degrees)
const accRoll = Math.atan2(accel.y, accel.z) * D;
const accPitch = Math.atan2(-accel.x, Math.sqrt(accel.y * accel.y + accel.z * accel.z)) * D;
let roll = context.get('roll');
let pitch = context.get('pitch');
if (roll === undefined) { roll = accRoll; pitch = accPitch; }
const alpha = 0.98;
roll = alpha * (roll + gyro.x * D * dt) + (1 - alpha) * accRoll;
pitch = alpha * (pitch + gyro.y * D * dt) + (1 - alpha) * accPitch;
context.set('roll', roll);
context.set('pitch', pitch);
msg.payload = { roll, pitch, temperature };
return msg;
